39	    Owner toOwner(OwnerFieldsDto ownerDto);
40	
41	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
42	
43	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
44	
45	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
46	        OwnerPageDto ownerPageDto = new OwnerPageDto();
47	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
48	        ownerPageDto.setPage(ownerPage.getNumber());
49	        ownerPageDto.setSize(ownerPage.getSize());
50	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
51	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
52	        return ownerPageDto;
53	    }
54	}
