1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Out;
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.mapper.OwnerMapper;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.util.BusinessDays;
11	
12	public class BuildOwner {
13	
14	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
15	        Owner owner = ownerMapper.toOwner(request);
16	        // When no registration date is supplied, default to the server's current date.
17	        if (owner.getRegistrationDate() == null) {
18	            owner.setRegistrationDate(LocalDate.now());
19	        }
20	        // The effective registration date must fall on a business day: a weekend rolls
21	        // forward to the next Monday. Everything derived from it (e.g. the membership
22	        // number's year segment) then uses the adjusted date.
23	        owner.setRegistrationDate(BusinessDays.toBusinessDay(owner.getRegistrationDate()));
24	        built.set(owner);
25	    }
26	}
