7	/** membership-levels: Replace the string membership tier with a numeric 'membershipLevel' from 1 to 3 on creatio... */
8	class AcceptanceTest extends AcceptanceBase {
9	
10		@Test
11		void coreNumericLevel() throws Exception {
12			ObjectNode o = ownerNode();
